def main():
    p = argparse.ArgumentParser()
    p.add_argument("--out", type=Path, required=True)
    args = p.parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    for i, (table, dl, dr, counts) in WITNESSES.items():
        assert emit(i, table, dl, dr, args.out) == counts
        for file in args.out.glob(f"Raw118Wide{i}*.lean"):
            new = file.with_name(file.name.replace("Raw118Wide", "Raw124OneLBWide"))
            new.write_text(file.read_text().replace("Raw118Wide", "Raw124OneLBWide").replace(
                "BB6Coverage.Agent1BiDFAWide", "BB6.Agent2Raw124OneLBWide"))
            file.unlink()
        print(i, len(dl)//2, len(dr)//2, counts, flush=True)

if __name__ == "__main__":
    main()
